INSERT OR IGNORE INTO course_curriculum_matches (course_id,module_id,match_type,confidence,notes) SELECT DISTINCT f.course_id,cm.id,'category_code',0.9,'Official PO-2021 module alias' FROM course_fields f JOIN json_each(f.value) je JOIN curriculum_module_aliases a ON a.normalized_alias=upper(replace(replace(replace(je.value,'-',''),' ',''),'.','')) JOIN curriculum_modules cm ON cm.id=a.module_id WHERE f.key='_categories_json';

INSERT OR IGNORE INTO course_curriculum_matches (course_id,module_id,match_type,confidence,notes) SELECT DISTINCT c.id,cm.id,'number_alias',0.9,'Official PO-2021 module alias' FROM courses c JOIN curriculum_module_aliases a ON a.normalized_alias=upper(replace(replace(replace(c.number,'-',''),' ',''),'.','')) JOIN curriculum_modules cm ON cm.id=a.module_id WHERE c.number IS NOT NULL;
